//go:build lithe_bundled_remote_server

package remoteserver

import "embed"

// The manifest and one <target>.bin per build are generated by scripts/desktop/package-desktop.sh
// from the stage of scripts/desktop/build-remote-server.sh; they are not tracked. The pattern
// fails the build when packaging copied no build.
//
//go:embed remote-server-manifest.json *.bin
var files embed.FS

func bundled() *source {
	manifest, err := files.ReadFile(ManifestFile)
	if err != nil {
		// The embed directive above guarantees the file; this cannot happen in a built client.
		panic(err)
	}
	return &source{
		manifest: manifest,
		build:    func(target string) ([]byte, error) { return files.ReadFile(target + ".bin") },
	}
}
